static SDL_GLContext  ctx;
static GLuint         VAO  = 0;
static GLuint         VBO  = 0;
static GLuint         prog = 0;

(cl-defmethod bad-grad-colors ((e elem) (beg string) (end string))
  (cl-loop
   initially (goto-char (pos-bol))
   with a = (bad-color-decimal beg)
   with o = (bad-color-decimal end)
   with w = (@ e w)
   with h = (@ e h)
   with n = (* w h)
   for (r g b) in (color-gradient a o n)
   for bgc = (color-rgb-to-hex r g b)
   for fgc = (color-complement bgc)
   for prp = (list :background bgc :foreground fgc)
   collect prp into props finally
